CREATE SCHEMA dasher_run_api AUTHORIZATION CURRENT_USER;

REVOKE ALL ON SCHEMA dasher_run_api
  FROM PUBLIC, dasher_app, dasher_security_definer,
    dasher_retention_definer, dasher_retention_operator,
    dasher_run_definer, dasher_run_operator;
GRANT USAGE ON SCHEMA dasher_run_api
  TO dasher_security_definer, dasher_run_definer, dasher_run_operator;
GRANT USAGE ON SCHEMA dasher, dasher_private TO dasher_run_definer;
GRANT USAGE ON SCHEMA dasher_api TO dasher_security_definer;

