CREATE FUNCTION dasher_private.uuid_v8_from_sha256_v1(p_identity_bytes bytea)
RETURNS uuid
LANGUAGE sql
IMMUTABLE
STRICT
SET search_path = pg_catalog
AS $function$
  SELECT (
    pg_catalog.substr(encoded.sha256_hex, 1, 12)
    || '8'
    || pg_catalog.substr(encoded.sha256_hex, 14, 3)
    || pg_catalog.to_hex(
      8 + (pg_catalog.get_byte(encoded.sha256_bytes, 8) & 3)
    )
    || pg_catalog.substr(encoded.sha256_hex, 18, 15)
  )::uuid
  FROM (
    SELECT pg_catalog.sha256(p_identity_bytes) AS sha256_bytes,
      pg_catalog.encode(pg_catalog.sha256(p_identity_bytes), 'hex')
        AS sha256_hex
  ) AS encoded
$function$;

REVOKE ALL ON FUNCTION dasher_private.uuid_v8_from_sha256_v1(bytea)
  FROM PUBLIC, dasher_app, dasher_security_definer,
    dasher_retention_definer, dasher_retention_operator,
    dasher_run_definer, dasher_run_operator;
GRANT EXECUTE ON FUNCTION dasher_private.uuid_v8_from_sha256_v1(bytea)
  TO dasher_security_definer, dasher_retention_definer, dasher_run_definer;

CREATE FUNCTION dasher_private.canonical_jsonb_bytes_v1(p_value jsonb)
RETURNS bytea
LANGUAGE plpgsql
IMMUTABLE
STRICT
SET search_path = pg_catalog
AS $function$
DECLARE
  v_json_stack jsonb[] := ARRAY[p_value];
  v_seen_stack boolean[] := ARRAY[false];
  v_render_stack text[] := ARRAY[]::text[];
  v_stack_index integer;
  v_current jsonb;
  v_child record;
  v_child_count integer;
  v_render_base integer;
  v_render text;
BEGIN
  WHILE pg_catalog.cardinality(v_json_stack) > 0 LOOP
    v_stack_index := pg_catalog.cardinality(v_json_stack);
    v_current := v_json_stack[v_stack_index];
    IF pg_catalog.jsonb_typeof(v_current) = 'string'
      AND NOT ((v_current #>> '{}') IS NFC NORMALIZED)
    THEN
      RETURN NULL;
    END IF;
    IF pg_catalog.jsonb_typeof(v_current) IN ('string','boolean','null') THEN
      v_render_stack := pg_catalog.array_append(
        v_render_stack, v_current::text
      );
      IF v_stack_index = 1 THEN
        v_json_stack := ARRAY[]::jsonb[];
        v_seen_stack := ARRAY[]::boolean[];
      ELSE
        v_json_stack := v_json_stack[1:v_stack_index - 1];
        v_seen_stack := v_seen_stack[1:v_stack_index - 1];
      END IF;
    ELSIF pg_catalog.jsonb_typeof(v_current) = 'number' THEN
      RETURN NULL;
    ELSIF NOT v_seen_stack[v_stack_index] THEN
      v_seen_stack[v_stack_index] := true;
      IF pg_catalog.jsonb_typeof(v_current) = 'object' THEN
        FOR v_child IN
          SELECT item.key, item.value
          FROM pg_catalog.jsonb_each(v_current) AS item(key, value)
          WHERE item.key IS NFC NORMALIZED
          ORDER BY pg_catalog.convert_to(item.key, 'UTF8') DESC
        LOOP
          v_json_stack := pg_catalog.array_append(
            v_json_stack, v_child.value
          );
          v_seen_stack := pg_catalog.array_append(v_seen_stack, false);
        END LOOP;
      ELSE
        FOR v_child IN
          SELECT item.value
          FROM pg_catalog.jsonb_array_elements(v_current)
            WITH ORDINALITY AS item(value, ordinal)
          ORDER BY item.ordinal DESC
        LOOP
          v_json_stack := pg_catalog.array_append(
            v_json_stack, v_child.value
          );
          v_seen_stack := pg_catalog.array_append(v_seen_stack, false);
        END LOOP;
      END IF;
    ELSE
      IF pg_catalog.jsonb_typeof(v_current) = 'object' THEN
        SELECT pg_catalog.count(*)::integer INTO v_child_count
        FROM pg_catalog.jsonb_object_keys(v_current);
        IF v_child_count <> (
          SELECT pg_catalog.count(*)::integer
          FROM pg_catalog.jsonb_object_keys(v_current) AS key_name
          WHERE key_name IS NFC NORMALIZED
        ) THEN
          RETURN NULL;
        END IF;
        v_render_base := pg_catalog.cardinality(v_render_stack)
          - v_child_count + 1;
        v_render := '{';
        FOR v_child IN
          SELECT item.key, item.ordinal
          FROM (
            SELECT key_name AS key,
              pg_catalog.row_number() OVER (
                ORDER BY pg_catalog.convert_to(key_name, 'UTF8')
              )::integer AS ordinal
            FROM pg_catalog.jsonb_object_keys(v_current) AS key_name
          ) AS item
          ORDER BY item.ordinal
        LOOP
          IF v_child.ordinal > 1 THEN v_render := v_render || ','; END IF;
          v_render := v_render || pg_catalog.to_json(v_child.key)::text
            || ':' || v_render_stack[v_render_base + v_child.ordinal - 1];
        END LOOP;
        v_render := v_render || '}';
      ELSE
        v_child_count := pg_catalog.jsonb_array_length(v_current);
        v_render_base := pg_catalog.cardinality(v_render_stack)
          - v_child_count + 1;
        v_render := '[';
        IF v_child_count > 0 THEN
          FOR v_stack_index IN 0..v_child_count - 1 LOOP
            IF v_stack_index > 0 THEN v_render := v_render || ','; END IF;
            v_render := v_render
              || v_render_stack[v_render_base + v_stack_index];
          END LOOP;
        END IF;
        v_render := v_render || ']';
        v_stack_index := pg_catalog.cardinality(v_json_stack);
      END IF;
      IF v_child_count > 0 THEN
        IF v_render_base = 1 THEN
          v_render_stack := ARRAY[]::text[];
        ELSE
          v_render_stack := v_render_stack[1:v_render_base - 1];
        END IF;
      END IF;
      v_render_stack := pg_catalog.array_append(v_render_stack, v_render);
      v_stack_index := pg_catalog.cardinality(v_json_stack);
      IF v_stack_index = 1 THEN
        v_json_stack := ARRAY[]::jsonb[];
        v_seen_stack := ARRAY[]::boolean[];
      ELSE
        v_json_stack := v_json_stack[1:v_stack_index - 1];
        v_seen_stack := v_seen_stack[1:v_stack_index - 1];
      END IF;
    END IF;
  END LOOP;
  IF pg_catalog.cardinality(v_render_stack) <> 1 THEN RETURN NULL; END IF;
  RETURN pg_catalog.convert_to(v_render_stack[1], 'UTF8');
END
$function$;

REVOKE ALL ON FUNCTION dasher_private.canonical_jsonb_bytes_v1(jsonb)
  FROM PUBLIC, dasher_app, dasher_security_definer,
    dasher_retention_definer, dasher_retention_operator,
    dasher_run_definer, dasher_run_operator;
GRANT EXECUTE ON FUNCTION dasher_private.canonical_jsonb_bytes_v1(jsonb)
  TO dasher_security_definer, dasher_retention_definer, dasher_run_definer;

CREATE TABLE dasher.agent_run_policy_revisions (
  policy_revision bigint NOT NULL,
  previous_policy_revision bigint,
  previous_policy_sha256 bytea,
  policy_sha256 bytea NOT NULL,
  enabled boolean NOT NULL,
  adapter_id text NOT NULL,
  model_id text NOT NULL,
  price_book_revision text NOT NULL,
  input_token_micros bigint NOT NULL,
  output_token_micros bigint NOT NULL,
  generation_limit_vector dasher_run_api.attempt_resource_vector NOT NULL,
  review_limit_vector dasher_run_api.attempt_resource_vector NOT NULL,
  active_organization_run_limit smallint NOT NULL,
  active_dashboard_run_limit smallint NOT NULL,
  approval_required_dashboard_limit smallint NOT NULL,
  provider_concurrency_limit smallint NOT NULL,
  tool_attempt_limit smallint NOT NULL,
  retry_limit smallint NOT NULL,
  planner_instructions_sha256 bytea NOT NULL,
  generator_instructions_sha256 bytea NOT NULL,
  specialist_instructions_sha256 bytea NOT NULL,
  repair_instructions_sha256 bytea NOT NULL,
  reviewer_instructions_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_run_policy_revisions_pkey PRIMARY KEY (policy_revision),
  CONSTRAINT agent_run_policy_revisions_uq_01 UNIQUE (policy_sha256),
  CONSTRAINT agent_run_policy_revisions_check_01 CHECK (policy_revision >= 1),
  CONSTRAINT agent_run_policy_revisions_check_02 CHECK (
    (policy_revision = 1) =
      (previous_policy_revision IS NULL AND previous_policy_sha256 IS NULL)
  ),
  CONSTRAINT agent_run_policy_revisions_check_03 CHECK (
    previous_policy_revision IS NULL
    OR previous_policy_revision = policy_revision - 1
  ),
  CONSTRAINT agent_run_policy_revisions_check_04 CHECK (
    octet_length(policy_sha256) = 32
    AND (previous_policy_sha256 IS NULL OR octet_length(previous_policy_sha256) = 32)
    AND octet_length(planner_instructions_sha256) = 32
    AND octet_length(generator_instructions_sha256) = 32
    AND octet_length(specialist_instructions_sha256) = 32
    AND octet_length(repair_instructions_sha256) = 32
    AND octet_length(reviewer_instructions_sha256) = 32
  ),
  CONSTRAINT agent_run_policy_revisions_check_05 CHECK (
    input_token_micros >= 0 AND output_token_micros >= 0
    AND active_organization_run_limit = 2
    AND active_dashboard_run_limit = 1
    AND approval_required_dashboard_limit = 2
    AND provider_concurrency_limit = 1
    AND tool_attempt_limit = 0
    AND retry_limit = 1
    AND adapter_id = 'fake-provider-v1'
    AND model_id = 'fake-model-v1'
    AND price_book_revision = 'fake-price-book-v1'
  )
);

CREATE TABLE dasher.run_service_principal_allowlist (
  run_service_principal_id uuid NOT NULL,
  principal_revision bigint NOT NULL,
  session_login name NOT NULL,
  enabled boolean NOT NULL,
  capabilities text[] NOT NULL,
  capabilities_sha256 bytea NOT NULL,
  previous_principal_revision bigint,
  previous_principal_sha256 bytea,
  principal_sha256 bytea NOT NULL,
  database_oid oid NOT NULL,
  database_name name NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT run_service_principal_allowlist_pkey PRIMARY KEY (
    run_service_principal_id, principal_revision
  ),
  CONSTRAINT run_service_principal_allowlist_uq_01 UNIQUE (
    session_login, database_oid, principal_revision
  ),
  CONSTRAINT run_service_principal_allowlist_uq_02 UNIQUE (principal_sha256),
  CONSTRAINT run_service_principal_allowlist_check_01 CHECK (principal_revision >= 1),
  CONSTRAINT run_service_principal_allowlist_check_02 CHECK (
    (principal_revision = 1) =
      (previous_principal_revision IS NULL AND previous_principal_sha256 IS NULL)
  ),
  CONSTRAINT run_service_principal_allowlist_check_03 CHECK (
    previous_principal_revision IS NULL
    OR previous_principal_revision = principal_revision - 1
  ),
  CONSTRAINT run_service_principal_allowlist_check_04 CHECK (
    octet_length(capabilities_sha256) = 32
    AND octet_length(principal_sha256) = 32
    AND (previous_principal_sha256 IS NULL OR octet_length(previous_principal_sha256) = 32)
  ),
  CONSTRAINT run_service_principal_allowlist_check_05 CHECK (
    cardinality(capabilities) BETWEEN 1 AND 21
    AND capabilities <@ ARRAY[
      'checkpoint', 'claim', 'clone_replay', 'close_candidate_set',
      'commit_abstention', 'commit_brief', 'commit_bundle', 'commit_candidate',
      'commit_claims', 'commit_graph', 'commit_manifest', 'commit_validation',
      'consume_replay', 'dispatch', 'finalize_ranking', 'finish', 'read_input',
      'read_replay', 'reconcile', 'release', 'reserve'
    ]::text[]
  )
);

CREATE TABLE dasher.agent_runs (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  run_request_id uuid NOT NULL,
  request_payload_id uuid,
  requesting_user_id uuid NOT NULL,
  requesting_membership_id uuid NOT NULL,
  requesting_authority_revision bigint NOT NULL,
  policy_revision bigint NOT NULL,
  requested_at timestamptz NOT NULL,
  state text NOT NULL,
  run_revision bigint NOT NULL,
  current_event_sequence bigint NOT NULL,
  current_event_sha256 bytea NOT NULL,
  lease_epoch bigint NOT NULL,
  lease_token_sha256 bytea,
  lease_owner_principal_id uuid,
  lease_owner_principal_revision bigint,
  lease_expires_at timestamptz,
  latest_checkpoint_revision bigint,
  candidate_set_sha256 bytea,
  candidate_set_closed_at timestamptz,
  terminal_at timestamptz,
  terminal_reason_sha256 bytea,
  selected_candidate_id uuid,
  consumed_replay_sequence bigint,
  consumed_replay_sha256 bytea,
  terminal_operation_kind text,
  terminal_operation_id uuid,
  terminal_claim_input_sha256 bytea,
  terminal_operation_sha256 bytea,
  tenant_cancel_operation_id uuid,
  tenant_cancel_operation_sha256 bytea,
  tenant_cancel_result_sha256 bytea,
  tenant_cancel_result_run_revision bigint,
  tenant_cancel_result_event_sequence bigint,
  tenant_cancel_result_event_sha256 bytea,
  CONSTRAINT agent_runs_pkey PRIMARY KEY (organization_id, dashboard_id, run_id),
  CONSTRAINT agent_runs_uq_01 UNIQUE (organization_id, run_id),
  CONSTRAINT agent_runs_uq_02 UNIQUE (organization_id, run_request_id),
  CONSTRAINT agent_runs_check_01 CHECK (
    state IN (
      'requested', 'authorized', 'planning', 'generating', 'revising',
      'validating', 'approval_required', 'accepted', 'rejected', 'cancelled',
      'expired', 'failed'
    )
  ),
  CONSTRAINT agent_runs_check_02 CHECK (
    state <> 'accepted' AND run_revision >= 1 AND current_event_sequence >= 1
    AND lease_epoch >= 0 AND octet_length(current_event_sha256) = 32
  ),
  CONSTRAINT agent_runs_check_03 CHECK (
    (lease_token_sha256 IS NULL AND lease_owner_principal_id IS NULL
      AND lease_owner_principal_revision IS NULL AND lease_expires_at IS NULL)
    OR
    (octet_length(lease_token_sha256) = 32 AND lease_owner_principal_id IS NOT NULL
      AND lease_owner_principal_revision >= 1 AND lease_expires_at IS NOT NULL)
  ),
  CONSTRAINT agent_runs_check_04 CHECK (
    (candidate_set_sha256 IS NULL) = (candidate_set_closed_at IS NULL)
    AND (candidate_set_sha256 IS NULL OR octet_length(candidate_set_sha256) = 32)
    AND (terminal_reason_sha256 IS NULL OR octet_length(terminal_reason_sha256) = 32)
    AND (consumed_replay_sha256 IS NULL OR octet_length(consumed_replay_sha256) = 32)
  ),
  CONSTRAINT agent_runs_check_05 CHECK (
    terminal_operation_kind IS NULL
    OR terminal_operation_kind IN ('abstention', 'ranking', 'finish', 'indeterminate_takeover')
  ),
  CONSTRAINT agent_runs_check_06 CHECK (
    (terminal_operation_kind IS NULL) = (terminal_operation_id IS NULL)
    AND (terminal_operation_kind = 'indeterminate_takeover') =
      (terminal_claim_input_sha256 IS NOT NULL AND terminal_operation_sha256 IS NOT NULL)
    AND (terminal_claim_input_sha256 IS NULL OR octet_length(terminal_claim_input_sha256) = 32)
    AND (terminal_operation_sha256 IS NULL OR octet_length(terminal_operation_sha256) = 32)
  ),
  CONSTRAINT agent_runs_check_07 CHECK (
    (tenant_cancel_operation_id IS NULL
      AND tenant_cancel_operation_sha256 IS NULL
      AND tenant_cancel_result_sha256 IS NULL
      AND tenant_cancel_result_run_revision IS NULL
      AND tenant_cancel_result_event_sequence IS NULL
      AND tenant_cancel_result_event_sha256 IS NULL)
    OR
    (tenant_cancel_operation_id IS NOT NULL
      AND octet_length(tenant_cancel_operation_sha256) = 32
      AND octet_length(tenant_cancel_result_sha256) = 32
      AND tenant_cancel_result_run_revision >= 1
      AND tenant_cancel_result_event_sequence >= 1
      AND octet_length(tenant_cancel_result_event_sha256) = 32
      AND state = 'cancelled')
  )
);

CREATE TABLE dasher.agent_run_request_payloads (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  request_payload_id uuid NOT NULL,
  run_request_id uuid NOT NULL,
  request_idempotency_sha256 bytea NOT NULL,
  content_nonce bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  request_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_run_request_payloads_pkey PRIMARY KEY (
    organization_id, dashboard_id, request_payload_id
  ),
  CONSTRAINT agent_run_request_payloads_uq_01 UNIQUE (organization_id, run_request_id),
  CONSTRAINT agent_run_request_payloads_check_01 CHECK (
    octet_length(request_idempotency_sha256) = 32
    AND octet_length(content_nonce) = 32
    AND octet_length(request_sha256) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 1114112
  )
);

CREATE TABLE dasher.agent_run_events (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  event_sequence bigint NOT NULL,
  event_id uuid NOT NULL,
  event_kind text NOT NULL,
  occurred_at timestamptz NOT NULL,
  prior_event_sequence bigint,
  prior_event_sha256 bytea,
  event_payload_id uuid,
  event_sha256 bytea NOT NULL,
  claim_operation_kind text,
  claim_request_id uuid,
  claim_input_sha256 bytea,
  claim_result_sha256 bytea,
  claim_result_run_revision bigint,
  claim_result_state text,
  claim_result_lease_epoch bigint,
  claim_result_attempt_token bytea,
  claim_result_lease_expires_at timestamptz,
  claim_result_policy_revision bigint,
  claim_result_input_sha256 bytea,
  CONSTRAINT agent_run_events_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, event_sequence
  ),
  CONSTRAINT agent_run_events_uq_01 UNIQUE (organization_id, event_id),
  CONSTRAINT agent_run_events_uq_02 UNIQUE (
    organization_id, dashboard_id, run_id, event_sha256
  ),
  CONSTRAINT agent_run_events_uq_03 UNIQUE (
    organization_id, dashboard_id, run_id, event_sequence, event_sha256
  ),
  CONSTRAINT agent_run_events_check_01 CHECK (event_sequence >= 1),
  CONSTRAINT agent_run_events_check_02 CHECK (
    (event_sequence = 1 AND prior_event_sequence IS NULL AND prior_event_sha256 IS NULL)
    OR
    (event_sequence > 1 AND prior_event_sequence = event_sequence - 1
      AND octet_length(prior_event_sha256) = 32)
  ),
  CONSTRAINT agent_run_events_check_03 CHECK (
    octet_length(event_sha256) = 32
    AND (claim_input_sha256 IS NULL OR octet_length(claim_input_sha256) = 32)
    AND (claim_result_sha256 IS NULL OR octet_length(claim_result_sha256) = 32)
    AND (claim_result_attempt_token IS NULL OR octet_length(claim_result_attempt_token) = 32)
    AND (claim_result_input_sha256 IS NULL OR octet_length(claim_result_input_sha256) = 32)
  ),
  CONSTRAINT agent_run_events_check_04 CHECK (
    (claim_operation_kind IS NULL AND claim_request_id IS NULL
      AND claim_input_sha256 IS NULL AND claim_result_sha256 IS NULL
      AND claim_result_run_revision IS NULL AND claim_result_state IS NULL
      AND claim_result_lease_epoch IS NULL AND claim_result_attempt_token IS NULL
      AND claim_result_lease_expires_at IS NULL
      AND claim_result_policy_revision IS NULL AND claim_result_input_sha256 IS NULL)
    OR
    (event_kind IN ('lease_acquired', 'indeterminate_quarantined')
      AND claim_operation_kind IN ('ordinary_claim', 'indeterminate_takeover')
      AND claim_request_id IS NOT NULL
      AND claim_result_run_revision >= 1
      AND claim_result_state IS NOT NULL
      AND claim_result_lease_epoch >= 1
      AND claim_result_policy_revision >= 1)
  )
);

CREATE TABLE dasher.agent_run_event_payloads (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  event_payload_id uuid NOT NULL,
  event_id uuid NOT NULL,
  event_sequence bigint NOT NULL,
  content_nonce bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  payload_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_run_event_payloads_pkey PRIMARY KEY (
    organization_id, dashboard_id, event_payload_id
  ),
  CONSTRAINT agent_run_event_payloads_uq_01 UNIQUE (organization_id, event_id),
  CONSTRAINT agent_run_event_payloads_uq_02 UNIQUE (
    organization_id, dashboard_id, run_id, event_sequence
  ),
  CONSTRAINT agent_run_event_payloads_check_01 CHECK (
    event_sequence >= 1 AND octet_length(content_nonce) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 1114112
    AND octet_length(payload_sha256) = 32
  )
);

CREATE TABLE dasher.agent_run_checkpoints (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  checkpoint_revision bigint NOT NULL,
  source_event_sequence bigint NOT NULL,
  source_event_sha256 bytea NOT NULL,
  state_sha256 bytea,
  checkpoint_sha256 bytea NOT NULL,
  checkpoint_payload_id uuid,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_run_checkpoints_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, checkpoint_revision
  ),
  CONSTRAINT agent_run_checkpoints_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id, source_event_sequence, source_event_sha256
  ),
  CONSTRAINT agent_run_checkpoints_check_01 CHECK (
    checkpoint_revision >= 1 AND source_event_sequence >= 1
    AND octet_length(source_event_sha256) = 32
    AND octet_length(checkpoint_sha256) = 32
    AND ((state_sha256 IS NULL AND checkpoint_payload_id IS NULL)
      OR (octet_length(state_sha256) = 32 AND checkpoint_payload_id IS NOT NULL))
  )
);

CREATE TABLE dasher.agent_run_checkpoint_payloads (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  checkpoint_payload_id uuid NOT NULL,
  checkpoint_revision bigint NOT NULL,
  content_nonce bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  state_sha256 bytea NOT NULL,
  checkpoint_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_run_checkpoint_payloads_pkey PRIMARY KEY (
    organization_id, dashboard_id, checkpoint_payload_id
  ),
  CONSTRAINT agent_run_checkpoint_payloads_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id, checkpoint_revision
  ),
  CONSTRAINT agent_run_checkpoint_payloads_check_01 CHECK (
    checkpoint_revision >= 1 AND octet_length(content_nonce) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 1114112
    AND octet_length(state_sha256) = 32 AND octet_length(checkpoint_sha256) = 32
  )
);

CREATE TABLE dasher.agent_run_budget_counters (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  partition text NOT NULL,
  vector_field text NOT NULL,
  limit_units bigint NOT NULL,
  reserved_units bigint NOT NULL,
  used_units bigint NOT NULL,
  released_units bigint NOT NULL,
  updated_at timestamptz NOT NULL,
  CONSTRAINT agent_run_budget_counters_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, partition, vector_field
  ),
  CONSTRAINT agent_run_budget_counters_uq_01 UNIQUE (
    organization_id, run_id, partition, vector_field
  ),
  CONSTRAINT agent_run_budget_counters_check_01 CHECK (
    partition IN ('generation', 'review')
    AND vector_field IN (
      'calls', 'candidates', 'specialist_attempts', 'reviewer_attempts',
      'repair_attempts', 'input_tokens', 'output_tokens', 'reasoning_tokens',
      'cache_read_tokens', 'cache_write_tokens', 'total_tokens', 'wall_millis',
      'work_millis', 'cost_micros'
    )
  ),
  CONSTRAINT agent_run_budget_counters_check_02 CHECK (
    limit_units >= 0 AND reserved_units >= 0 AND used_units >= 0
    AND released_units >= 0 AND used_units + released_units <= reserved_units
    AND reserved_units - used_units - released_units <= limit_units
  )
);

CREATE TABLE dasher.agent_run_calculation_meters (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  meter_id uuid NOT NULL,
  graph_id uuid NOT NULL,
  result_id uuid NOT NULL,
  meter_vector dasher_run_api.calculation_meter_vector_v1 NOT NULL,
  meter_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_run_calculation_meters_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, meter_id
  ),
  CONSTRAINT agent_run_calculation_meters_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id, graph_id
  ),
  CONSTRAINT agent_run_calculation_meters_uq_02 UNIQUE (
    organization_id, dashboard_id, run_id, result_id
  ),
  CONSTRAINT agent_run_calculation_meters_check_01 CHECK (
    octet_length(meter_sha256) = 32
  )
);

CREATE TABLE dasher.agent_run_attempts (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  attempt_id uuid NOT NULL,
  lease_epoch bigint NOT NULL,
  partition text NOT NULL,
  attempt_kind text NOT NULL,
  candidate_slot smallint,
  retry_of_attempt_id uuid,
  state text NOT NULL,
  request_payload_id uuid,
  result_payload_id uuid,
  reserved_vector dasher_run_api.attempt_resource_vector NOT NULL,
  actual_vector dasher_run_api.attempt_resource_vector,
  used_vector dasher_run_api.attempt_resource_vector NOT NULL,
  released_vector dasher_run_api.attempt_resource_vector NOT NULL,
  outstanding_vector dasher_run_api.attempt_resource_vector NOT NULL,
  reserved_at timestamptz NOT NULL,
  dispatch_ready_at timestamptz,
  dispatch_started_at timestamptz,
  reconciled_at timestamptz,
  terminal_reason_sha256 bytea,
  CONSTRAINT agent_run_attempts_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, attempt_id
  ),
  CONSTRAINT agent_run_attempts_uq_01 UNIQUE (organization_id, run_id, attempt_id),
  CONSTRAINT agent_run_attempts_check_01 CHECK (
    lease_epoch >= 1 AND partition IN ('generation', 'review')
    AND attempt_kind IN ('planner', 'generator', 'specialist', 'repair', 'reviewer')
    AND state IN (
      'reserved_pre_dispatch', 'dispatch_ready', 'dispatch_started', 'succeeded',
      'refused_charged', 'failed_charged', 'released_pre_dispatch',
      'released_takeover', 'cancelled_released', 'cancelled_charged',
      'indeterminate_quarantined'
    )
  ),
  CONSTRAINT agent_run_attempts_check_02 CHECK (
    (attempt_kind = 'generator' AND candidate_slot BETWEEN 1 AND 2)
    OR (attempt_kind <> 'generator' AND candidate_slot IS NULL)
  ),
  CONSTRAINT agent_run_attempts_check_03 CHECK (
    (terminal_reason_sha256 IS NULL OR octet_length(terminal_reason_sha256) = 32)
    AND NOT (state IN ('reserved_pre_dispatch', 'dispatch_ready', 'dispatch_started')
      AND reconciled_at IS NOT NULL)
  )
);

CREATE TABLE dasher.agent_run_attempt_payloads (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  attempt_id uuid NOT NULL,
  payload_kind text NOT NULL,
  payload_id uuid NOT NULL,
  content_nonce bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  payload_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_run_attempt_payloads_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, attempt_id, payload_kind, payload_id
  ),
  CONSTRAINT agent_run_attempt_payloads_uq_01 UNIQUE (organization_id, payload_id),
  CONSTRAINT agent_run_attempt_payloads_uq_02 UNIQUE (
    organization_id, dashboard_id, run_id, attempt_id, payload_id
  ),
  CONSTRAINT agent_run_attempt_payloads_uq_03 UNIQUE (
    organization_id, dashboard_id, run_id, attempt_id, payload_kind
  ),
  CONSTRAINT agent_run_attempt_payloads_check_01 CHECK (
    payload_kind IN ('request', 'result') AND octet_length(content_nonce) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 1114112
    AND octet_length(payload_sha256) = 32
  )
);

CREATE TABLE dasher.agent_recorded_results (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  result_sequence bigint NOT NULL,
  result_id uuid NOT NULL,
  attempt_id uuid,
  result_payload_id uuid,
  replay_source_run_id uuid,
  replay_source_result_sequence bigint,
  replay_source_result_sha256 bytea,
  result_kind text NOT NULL,
  canonical_bytes bytea NOT NULL,
  result_sha256 bytea NOT NULL,
  prior_result_head_sha256 bytea,
  result_head_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_recorded_results_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, result_sequence
  ),
  CONSTRAINT agent_recorded_results_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id, result_id
  ),
  CONSTRAINT agent_recorded_results_check_01 CHECK (
    result_sequence BETWEEN 1 AND 5
    AND octet_length(result_sha256) = 32
    AND octet_length(result_head_sha256) = 32
    AND (prior_result_head_sha256 IS NULL OR octet_length(prior_result_head_sha256) = 32)
  ),
  CONSTRAINT agent_recorded_results_check_02 CHECK (
    (attempt_id IS NOT NULL AND result_payload_id IS NOT NULL
      AND replay_source_run_id IS NULL AND replay_source_result_sequence IS NULL
      AND replay_source_result_sha256 IS NULL)
    OR
    (attempt_id IS NULL AND result_payload_id IS NULL
      AND replay_source_run_id IS NOT NULL AND replay_source_result_sequence >= 1
      AND octet_length(replay_source_result_sha256) = 32)
  ),
  CONSTRAINT agent_recorded_results_check_03 CHECK (
    result_kind IN (
      'planner_output', 'specialist_output', 'candidate_output',
      'candidate_invalid', 'repair_output', 'reviewer_verdict_set',
      'refusal', 'failure'
    )
  )
);

CREATE TABLE dasher.field_catalog_snapshots (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  catalog_snapshot_id uuid NOT NULL,
  input_snapshot_id uuid NOT NULL,
  input_sha256 bytea NOT NULL,
  input_row_count bigint NOT NULL,
  catalog_sha256 bytea NOT NULL,
  evaluated_at timestamptz NOT NULL,
  canonical_bytes bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT field_catalog_snapshots_pkey PRIMARY KEY (
    organization_id, dashboard_id, catalog_snapshot_id
  ),
  CONSTRAINT field_catalog_snapshots_uq_01 UNIQUE (
    organization_id, dashboard_id, catalog_sha256
  ),
  CONSTRAINT field_catalog_snapshots_check_01 CHECK (
    input_row_count BETWEEN 0 AND 10000 AND octet_length(input_sha256) = 32
    AND octet_length(catalog_sha256) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 1048576
  )
);

CREATE TABLE dasher.field_catalog_entries (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  catalog_snapshot_id uuid NOT NULL,
  field_id uuid NOT NULL,
  source_path text NOT NULL,
  logical_name text NOT NULL,
  scalar_type text NOT NULL,
  nullable boolean NOT NULL,
  semantic_type text NOT NULL,
  unit text,
  currency text,
  grain text,
  event_time_field_id uuid,
  stable_key_ordinal integer,
  max_value_bytes bigint NOT NULL,
  allowed_aggregations text[] NOT NULL,
  allowed_dimensions uuid[] NOT NULL,
  lineage_evidence_ids uuid[] NOT NULL,
  entry_sha256 bytea NOT NULL,
  CONSTRAINT field_catalog_entries_pkey PRIMARY KEY (
    organization_id, dashboard_id, catalog_snapshot_id, field_id
  ),
  CONSTRAINT field_catalog_entries_check_01 CHECK (
    scalar_type IN ('boolean', 'integer', 'decimal', 'text', 'date', 'timestamp')
    AND max_value_bytes BETWEEN 1 AND 1048576
    AND (stable_key_ordinal IS NULL OR stable_key_ordinal >= 0)
    AND octet_length(entry_sha256) = 32
  )
);

CREATE TABLE dasher.metric_contract_versions (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  contract_set_id uuid NOT NULL,
  contract_set_sha256 bytea NOT NULL,
  contract_id uuid NOT NULL,
  contract_version bigint NOT NULL,
  catalog_snapshot_id uuid NOT NULL,
  business_owner_membership_id uuid NOT NULL,
  data_owner_membership_id uuid NOT NULL,
  name text NOT NULL,
  definition text NOT NULL,
  measure_field_id uuid NOT NULL,
  aggregation text NOT NULL,
  denominator_contract_id uuid,
  denominator_contract_version bigint,
  value_type text NOT NULL,
  unit text,
  currency text,
  direction text NOT NULL,
  threshold text,
  target text,
  grain text NOT NULL,
  lag_millis bigint NOT NULL,
  freshness_slo_millis bigint NOT NULL,
  allowed_dimension_field_ids uuid[] NOT NULL,
  calendar text NOT NULL,
  timezone text NOT NULL,
  lineage_evidence_ids uuid[] NOT NULL,
  review_state text NOT NULL,
  contract_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT metric_contract_versions_pkey PRIMARY KEY (
    organization_id, dashboard_id, contract_id, contract_version
  ),
  CONSTRAINT metric_contract_versions_uq_01 UNIQUE (
    organization_id, dashboard_id, contract_set_id, contract_id, contract_version
  ),
  CONSTRAINT metric_contract_versions_uq_02 UNIQUE (
    organization_id, dashboard_id, contract_sha256
  ),
  CONSTRAINT metric_contract_versions_check_01 CHECK (
    contract_version >= 1 AND octet_length(contract_set_sha256) = 32
    AND octet_length(contract_sha256) = 32
    AND business_owner_membership_id <> data_owner_membership_id
    AND lag_millis >= 0 AND freshness_slo_millis >= 0
    AND review_state = 'reviewed'
  ),
  CONSTRAINT metric_contract_versions_check_02 CHECK (
    (denominator_contract_id IS NULL) = (denominator_contract_version IS NULL)
    AND (denominator_contract_version IS NULL OR denominator_contract_version >= 1)
    AND aggregation IN (
      'count','count_distinct','sum','min','max','mean','median','ratio'
    )
    AND value_type IN ('integer','decimal','currency','percentage','duration')
    AND direction IN (
      'higher_is_better','lower_is_better','target_band','neutral'
    )
    AND calendar IN ('gregorian','iso_week','fiscal_445')
    AND lag_millis BETWEEN 0 AND 31536000000
    AND freshness_slo_millis BETWEEN 1 AND 31536000000
    AND pg_catalog.cardinality(allowed_dimension_field_ids) BETWEEN 0 AND 32
    AND pg_catalog.cardinality(lineage_evidence_ids) BETWEEN 1 AND 64
    AND (aggregation = 'ratio') = (denominator_contract_id IS NOT NULL)
    AND ((direction = 'neutral' AND threshold IS NULL AND target IS NULL)
      OR (direction <> 'neutral' AND threshold IS NOT NULL AND target IS NOT NULL))
  )
);

CREATE TABLE dasher.calculation_graphs (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  graph_id uuid NOT NULL,
  contract_set_id uuid NOT NULL,
  contract_id uuid NOT NULL,
  contract_version bigint NOT NULL,
  catalog_snapshot_id uuid NOT NULL,
  common_bundle_id uuid NOT NULL,
  freshness_classifier_node_id uuid,
  freshness_input_node_id uuid,
  freshness_source_row_id uuid,
  graph_sha256 bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT calculation_graphs_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, graph_id
  ),
  CONSTRAINT calculation_graphs_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id, graph_sha256
  ),
  CONSTRAINT calculation_graphs_check_01 CHECK (
    contract_version >= 1 AND octet_length(graph_sha256) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 65536
    AND ((freshness_classifier_node_id IS NULL AND freshness_input_node_id IS NULL
      AND freshness_source_row_id IS NULL)
      OR (freshness_classifier_node_id IS NOT NULL
        AND freshness_input_node_id IS NOT NULL
        AND freshness_source_row_id IS NOT NULL))
  )
);

CREATE TABLE dasher.calculation_results (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  result_id uuid NOT NULL,
  graph_id uuid NOT NULL,
  result_sha256 bytea NOT NULL,
  meter_sha256 bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT calculation_results_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, result_id
  ),
  CONSTRAINT calculation_results_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id, graph_id
  ),
  CONSTRAINT calculation_results_uq_02 UNIQUE (
    organization_id, dashboard_id, run_id, result_sha256
  ),
  CONSTRAINT calculation_results_check_01 CHECK (
    octet_length(result_sha256) = 32 AND octet_length(meter_sha256) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 1114112
  )
);

CREATE TABLE dasher.briefs (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  brief_id uuid NOT NULL,
  common_bundle_id uuid NOT NULL,
  brief_sha256 bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT briefs_pkey PRIMARY KEY (organization_id, dashboard_id, run_id, brief_id),
  CONSTRAINT briefs_uq_01 UNIQUE (organization_id, dashboard_id, run_id),
  CONSTRAINT briefs_uq_02 UNIQUE (organization_id, dashboard_id, run_id, brief_sha256),
  CONSTRAINT briefs_check_01 CHECK (
    octet_length(brief_sha256) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 32768
  )
);

CREATE TABLE dasher.candidate_comparison_bundles (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  bundle_id uuid NOT NULL,
  source_snapshot_id uuid NOT NULL,
  evidence_count bigint NOT NULL,
  bundle_sha256 bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT candidate_comparison_bundles_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, bundle_id
  ),
  CONSTRAINT candidate_comparison_bundles_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id
  ),
  CONSTRAINT candidate_comparison_bundles_uq_02 UNIQUE (
    organization_id, dashboard_id, run_id, bundle_sha256
  ),
  CONSTRAINT candidate_comparison_bundles_check_01 CHECK (
    evidence_count BETWEEN 1 AND 256 AND octet_length(bundle_sha256) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 262144
  )
);

CREATE TABLE dasher.candidate_comparison_bundle_evidence (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  bundle_id uuid NOT NULL,
  evidence_id uuid NOT NULL,
  source_snapshot_id uuid NOT NULL,
  evidence_sha256 bytea NOT NULL,
  source_sha256 bytea NOT NULL,
  freshness text NOT NULL,
  observed_at timestamptz NOT NULL,
  CONSTRAINT candidate_comparison_bundle_evidence_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, bundle_id, evidence_id
  ),
  CONSTRAINT candidate_comparison_bundle_evidence_check_01 CHECK (
    octet_length(evidence_sha256) = 32 AND octet_length(source_sha256) = 32
    AND freshness IN ('current', 'stale')
  )
);

CREATE TABLE dasher.agent_candidates (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  candidate_id uuid NOT NULL,
  brief_id uuid NOT NULL,
  common_bundle_id uuid NOT NULL,
  source_result_id uuid NOT NULL,
  source_result_sha256 bytea NOT NULL,
  precommit_validation_sha256 bytea NOT NULL,
  candidate_spec_sha256 bytea NOT NULL,
  material_claim_count bigint NOT NULL,
  material_claim_set_sha256 bytea NOT NULL,
  validation_state text NOT NULL,
  review_state text NOT NULL,
  manifest_sha256 bytea,
  rank integer,
  selected boolean NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_candidates_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, candidate_id
  ),
  CONSTRAINT agent_candidates_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id, candidate_spec_sha256
  ),
  CONSTRAINT agent_candidates_check_01 CHECK (
    octet_length(source_result_sha256) = 32
    AND octet_length(precommit_validation_sha256) = 32
    AND octet_length(candidate_spec_sha256) = 32
    AND material_claim_count BETWEEN 1 AND 64
    AND octet_length(material_claim_set_sha256) = 32
    AND (manifest_sha256 IS NULL OR octet_length(manifest_sha256) = 32)
    AND (rank IS NULL OR rank BETWEEN 1 AND 2)
  ),
  CONSTRAINT agent_candidates_check_02 CHECK (
    validation_state IN ('pending', 'valid', 'invalid')
    AND review_state IN ('pending', 'approved', 'rejected')
    AND (NOT selected OR (rank IS NOT NULL AND validation_state = 'valid'
      AND review_state = 'approved' AND manifest_sha256 IS NOT NULL))
  )
);

CREATE TABLE dasher.agent_candidate_payloads (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  candidate_id uuid NOT NULL,
  canonical_bytes bytea NOT NULL,
  candidate_spec_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_candidate_payloads_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, candidate_id
  ),
  CONSTRAINT agent_candidate_payloads_check_01 CHECK (
    octet_length(canonical_bytes) BETWEEN 1 AND 1048576
    AND octet_length(candidate_spec_sha256) = 32
  )
);

CREATE TABLE dasher.agent_validation_findings (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  candidate_id uuid NOT NULL,
  finding_count integer NOT NULL,
  validation_state text NOT NULL,
  findings_sha256 bytea NOT NULL,
  canonical_bytes bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT agent_validation_findings_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, candidate_id
  ),
  CONSTRAINT agent_validation_findings_check_01 CHECK (
    finding_count BETWEEN 0 AND 64
    AND validation_state IN ('valid', 'invalid')
    AND octet_length(findings_sha256) = 32
    AND octet_length(canonical_bytes) BETWEEN 1 AND 65536
  )
);

CREATE TABLE dasher.claims (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  run_id uuid NOT NULL,
  candidate_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  json_pointer text NOT NULL,
  assertion_sha256 bytea NOT NULL,
  label text NOT NULL,
  statement text NOT NULL,
  salience text NOT NULL,
  evidence_state text NOT NULL,
  calculation_result_id uuid,
  calculation_output_identity_kind text,
  calculation_output_node_id uuid,
  calculation_output_sha256 bytea,
  calculation_output_row_id uuid,
  calculation_output_field_id uuid,
  calculation_output_value_sha256 bytea,
  claim_set_sha256 bytea NOT NULL,
  claim_sha256 bytea NOT NULL,
  created_at timestamptz NOT NULL,
  CONSTRAINT claims_pkey PRIMARY KEY (
    organization_id, dashboard_id, run_id, candidate_id, claim_id
  ),
  CONSTRAINT claims_uq_01 UNIQUE (
    organization_id, dashboard_id, run_id, candidate_id, json_pointer
  ),
  CONSTRAINT claims_check_01 CHECK (
    octet_length(assertion_sha256) = 32 AND octet_length(claim_set_sha256) = 32
    AND octet_length(claim_sha256) = 32
    AND label IN (
      'observed','calculated','hypothesis','recommendation','unknown','blocked'
    )
    AND salience IN ('high','normal')
    AND evidence_state IN (
      'complete','partial','contradicted','stale','unsupported'
    )
    AND octet_length(json_pointer) BETWEEN 1 AND 512
    AND json_pointer ~ '^(?:/(?:[^~/[:cntrl:]]|~0|~1)*)+$'
    AND statement = json_pointer || ' sha256:' || encode(assertion_sha256, 'hex')
  ),
  CONSTRAINT claims_check_02 CHECK (
    (label <> 'calculated' AND calculation_result_id IS NULL
      AND calculation_output_identity_kind IS NULL
      AND calculation_output_node_id IS NULL AND calculation_output_sha256 IS NULL
      AND calculation_output_row_id IS NULL AND calculation_output_field_id IS NULL
      AND calculation_output_value_sha256 IS NULL)
    OR
    (label = 'calculated' AND calculation_result_id IS NOT NULL
      AND calculation_output_identity_kind IN ('output', 'scalar_row', 'rowset_cell')
      AND calculation_output_node_id IS NOT NULL
      AND octet_length(calculation_output_sha256) = 32
      AND ((calculation_output_identity_kind = 'output'
          AND calculation_output_row_id IS NULL
          AND calculation_output_field_id IS NULL
          AND calculation_output_value_sha256 IS NULL)
        OR (calculation_output_identity_kind = 'scalar_row'
          AND calculation_output_row_id IS NOT NULL
          AND calculation_output_field_id IS NULL
          AND octet_length(calculation_output_value_sha256) = 32)
        OR (calculation_output_identity_kind = 'rowset_cell'
          AND calculation_output_row_id IS NOT NULL
          AND calculation_output_field_id IS NOT NULL
          AND octet_length(calculation_output_value_sha256) = 32)))
  )
);

