CREATE TABLE dasher.dashboard_agent_drain_proofs (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  proof_id uuid NOT NULL,
  lifecycle_revision bigint NOT NULL,
  cleanup_attempt_id uuid NOT NULL,
  cleanup_lease_owner text NOT NULL,
  cleanup_lease_expires_at timestamptz NOT NULL,
  retention_principal_id uuid NOT NULL,
  retention_principal_revision bigint NOT NULL,
  pre_drain_run_count bigint NOT NULL,
  cancelled_run_count bigint NOT NULL,
  released_attempt_count bigint NOT NULL,
  charged_attempt_count bigint NOT NULL,
  remaining_nonterminal_run_count bigint NOT NULL,
  remaining_claimed_run_count bigint NOT NULL,
  first_event_run_id uuid,
  first_event_sequence bigint,
  first_event_sha256 bytea,
  last_event_run_id uuid,
  last_event_sequence bigint,
  last_event_sha256 bytea,
  event_count bigint NOT NULL,
  event_range_sha256 bytea NOT NULL,
  generated_at timestamptz NOT NULL,
  drain_request_proof_sha256 bytea NOT NULL,
  drain_proof_sha256 bytea NOT NULL,
  CONSTRAINT dashboard_agent_drain_proofs_pkey PRIMARY KEY (
    organization_id, dashboard_id, proof_id
  ),
  CONSTRAINT dashboard_agent_drain_proofs_uq_01 UNIQUE (
    organization_id, dashboard_id, proof_id, drain_proof_sha256
  ),
  CONSTRAINT dashboard_agent_drain_proofs_uq_02 UNIQUE (
    organization_id, dashboard_id, drain_request_proof_sha256
  ),
  CONSTRAINT dashboard_agent_drain_proofs_uq_03 UNIQUE (
    organization_id, dashboard_id, drain_proof_sha256
  ),
  CONSTRAINT dashboard_agent_drain_proofs_check_01 CHECK (
    proof_id = cleanup_attempt_id AND lifecycle_revision >= 1
    AND retention_principal_revision >= 1
    AND pre_drain_run_count >= 0 AND cancelled_run_count >= 0
    AND released_attempt_count >= 0 AND charged_attempt_count >= 0
    AND remaining_nonterminal_run_count = 0 AND remaining_claimed_run_count = 0
    AND event_count >= 0 AND octet_length(event_range_sha256) = 32
    AND octet_length(drain_request_proof_sha256) = 32
    AND octet_length(drain_proof_sha256) = 32
  ),
  CONSTRAINT dashboard_agent_drain_proofs_check_02 CHECK (
    (event_count = 0 AND first_event_run_id IS NULL
      AND first_event_sequence IS NULL AND first_event_sha256 IS NULL
      AND last_event_run_id IS NULL AND last_event_sequence IS NULL
      AND last_event_sha256 IS NULL)
    OR
    (event_count > 0 AND first_event_run_id IS NOT NULL
      AND first_event_sequence >= 1 AND octet_length(first_event_sha256) = 32
      AND last_event_run_id IS NOT NULL AND last_event_sequence >= 1
      AND octet_length(last_event_sha256) = 32
      AND (first_event_run_id, first_event_sequence)
        <= (last_event_run_id, last_event_sequence))
  )
);

CREATE TABLE dasher.dashboard_agent_drain_proof_consumptions (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  proof_id uuid NOT NULL,
  lifecycle_revision bigint NOT NULL,
  drain_proof_sha256 bytea NOT NULL,
  preceding_cleanup_attempt_id uuid NOT NULL,
  preceding_cleanup_lease_owner text NOT NULL,
  preceding_cleanup_lease_expires_at timestamptz NOT NULL,
  new_cleanup_lease_owner text NOT NULL,
  new_cleanup_lease_expires_at timestamptz NOT NULL,
  claim_event_and_audit_id uuid NOT NULL,
  consumed_at timestamptz NOT NULL,
  retention_principal_id uuid NOT NULL,
  retention_principal_revision bigint NOT NULL,
  consumption_sha256 bytea NOT NULL,
  CONSTRAINT dashboard_agent_drain_proof_consumptions_pkey PRIMARY KEY (
    organization_id, dashboard_id, proof_id
  ),
  CONSTRAINT dashboard_agent_drain_proof_consumptions_uq_01 UNIQUE (
    organization_id, dashboard_id, claim_event_and_audit_id
  ),
  CONSTRAINT dashboard_agent_drain_proof_consumptions_uq_02 UNIQUE (
    organization_id, dashboard_id, consumption_sha256
  ),
  CONSTRAINT dashboard_agent_drain_proof_consumptions_check_01 CHECK (
    lifecycle_revision >= 1 AND octet_length(drain_proof_sha256) = 32
    AND new_cleanup_lease_expires_at > consumed_at
    AND retention_principal_revision >= 1
    AND octet_length(consumption_sha256) = 32
  )
);

CREATE TABLE dasher.dashboard_agent_run_age_out_proofs (
  organization_id uuid NOT NULL,
  dashboard_id uuid NOT NULL,
  age_out_operation_id uuid NOT NULL,
  lifecycle_revision bigint NOT NULL,
  source_purge_proof_sha256 bytea NOT NULL,
  backup_deletion_proof_sha256 bytea NOT NULL,
  eligible_run_count bigint NOT NULL,
  deleted_run_count bigint NOT NULL,
  deleted_event_count bigint NOT NULL,
  deleted_checkpoint_count bigint NOT NULL,
  deleted_attempt_count bigint NOT NULL,
  deleted_counter_count bigint NOT NULL,
  deleted_drain_proof_consumption_count bigint NOT NULL,
  deleted_drain_proof_count bigint NOT NULL,
  retained_chain_head_sha256 bytea NOT NULL,
  retained_event_count bigint NOT NULL,
  deleted_at timestamptz NOT NULL,
  retention_principal_id uuid NOT NULL,
  retention_principal_revision bigint NOT NULL,
  age_out_proof_sha256 bytea NOT NULL,
  CONSTRAINT dashboard_agent_run_age_out_proofs_pkey PRIMARY KEY (
    organization_id, dashboard_id, age_out_operation_id
  ),
  CONSTRAINT dashboard_agent_run_age_out_proofs_uq_01 UNIQUE (
    organization_id, dashboard_id, lifecycle_revision
  ),
  CONSTRAINT dashboard_agent_run_age_out_proofs_uq_02 UNIQUE (
    organization_id, dashboard_id, age_out_proof_sha256
  ),
  CONSTRAINT dashboard_agent_run_age_out_proofs_check_01 CHECK (
    lifecycle_revision >= 1 AND octet_length(source_purge_proof_sha256) = 32
    AND octet_length(backup_deletion_proof_sha256) = 32
    AND eligible_run_count >= 0 AND eligible_run_count = deleted_run_count
    AND deleted_event_count >= 0 AND deleted_checkpoint_count >= 0
    AND deleted_attempt_count >= 0 AND deleted_counter_count >= 0
    AND deleted_drain_proof_consumption_count >= 0
    AND deleted_drain_proof_count >= 0
    AND retained_event_count = deleted_event_count
    AND octet_length(retained_chain_head_sha256) = 32
    AND retention_principal_revision >= 1
    AND octet_length(age_out_proof_sha256) = 32
  )
);

