CREATE FUNCTION dasher_private.run_policy_allows_v1(
  p_organization_id uuid,
  p_dashboard_id uuid,
  p_run_id uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog
AS $function$
  SELECT current_user = 'dasher_run_definer'::name
    AND current_setting('dasher.run_phase', true) IN (
      'authorized', 'checkpoint_replay'
    )
    AND p_organization_id = NULLIF(current_setting(
      'dasher.run_organization_id', true
    ), '')::uuid
    AND p_dashboard_id = NULLIF(current_setting(
      'dasher.run_dashboard_id', true
    ), '')::uuid
    AND p_run_id = NULLIF(current_setting('dasher.run_id', true), '')::uuid
    AND NULLIF(current_setting('dasher.run_request_id', true), '') IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM dasher.run_service_principal_allowlist AS principal
      WHERE principal.run_service_principal_id = NULLIF(current_setting(
          'dasher.run_principal_id', true
        ), '')::uuid
        AND principal.principal_revision = NULLIF(current_setting(
          'dasher.run_principal_revision', true
        ), '')::bigint
        AND principal.session_login = session_user
        AND principal.database_name = pg_catalog.current_database()
        AND principal.enabled
        AND NULLIF(current_setting(
          'dasher.run_capability', true
        ), '') = ANY(principal.capabilities)
        AND NOT EXISTS (
          SELECT 1
          FROM dasher.run_service_principal_allowlist AS later
          WHERE later.run_service_principal_id =
              principal.run_service_principal_id
            AND later.principal_revision > principal.principal_revision
        )
    )
    AND EXISTS (
      SELECT 1
      FROM dasher.memberships AS membership
      WHERE membership.organization_id = p_organization_id
        AND membership.membership_id = NULLIF(current_setting(
          'dasher.run_membership_id', true
        ), '')::uuid
        AND membership.user_id = NULLIF(current_setting(
          'dasher.run_user_id', true
        ), '')::uuid
        AND membership.authority_revision = NULLIF(current_setting(
          'dasher.run_authority_revision', true
        ), '')::bigint
        AND membership.state = 'active'
        AND membership.role IN ('editor', 'admin')
        AND membership.revoked_at IS NULL
    )
    AND EXISTS (
      SELECT 1
      FROM dasher.agent_run_policy_revisions AS policy
      WHERE policy.policy_revision = NULLIF(current_setting(
          'dasher.run_policy_revision', true
        ), '')::bigint
        AND policy.enabled
        AND NOT EXISTS (
          SELECT 1 FROM dasher.agent_run_policy_revisions AS later
          WHERE later.policy_revision > policy.policy_revision
        )
    )
    AND EXISTS (
      SELECT 1
      FROM dasher.dashboard_lifecycle_policies AS lifecycle_policy
      WHERE lifecycle_policy.organization_id = p_organization_id
        AND lifecycle_policy.policy_revision >= 1
        AND lifecycle_policy.retention_policy_revision >= 1
    )
    AND EXISTS (
      SELECT 1
      FROM dasher.dashboards AS dashboard
      WHERE dashboard.organization_id = p_organization_id
        AND dashboard.dashboard_id = p_dashboard_id
        AND dashboard.lifecycle_state IN ('draft', 'active')
        AND dashboard.access_revoked_at IS NULL
        AND dashboard.purged_at IS NULL
        AND NOT (
          dashboard.current_kind = 'disposable'
          AND dashboard.effective_expires_at IS NOT NULL
          AND pg_catalog.statement_timestamp() >=
            dashboard.effective_expires_at
        )
    )
$function$;

CREATE FUNCTION dasher_private.retention_policy_allows_v1(
  p_organization_id uuid,
  p_dashboard_id uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog
AS $function$
  SELECT current_user = 'dasher_retention_definer'::name
    AND current_setting('dasher.retention_phase', true) = 'authorized'
    AND COALESCE(current_setting(
      'dasher.retention_principal_id', true
    ), '') <> ''
    AND COALESCE(current_setting(
      'dasher.retention_principal_revision', true
    ), '') <> ''
    AND current_setting('dasher.retention_authority_scope', true)
      = 'platform_operator'
    AND current_setting('dasher.retention_capability', true) IN (
      'claim_cleanup', 'record_attempt', 'purge'
    )
    AND EXISTS (
      SELECT 1
      FROM dasher.retention_service_principal_allowlist AS principal
      WHERE principal.retention_service_principal_id = NULLIF(current_setting(
          'dasher.retention_principal_id', true
        ), '')::uuid
        AND principal.principal_revision = NULLIF(current_setting(
          'dasher.retention_principal_revision', true
        ), '')::bigint
        AND principal.binding_kind = 'postgres_session_user'
        AND principal.binding_subject = session_user
        AND principal.authority_scope = 'platform_operator'
        AND principal.scope_organization_id IS NULL
        AND principal.enabled AND principal.can_initialize
        AND NOT EXISTS (
          SELECT 1
          FROM dasher.retention_service_principal_allowlist AS later
          WHERE later.retention_service_principal_id
            = principal.retention_service_principal_id
            AND later.principal_revision > principal.principal_revision
        )
    )
    AND p_organization_id = NULLIF(current_setting(
      'dasher.retention_target_organization_id', true
    ), '')::uuid
    AND p_dashboard_id = NULLIF(current_setting(
      'dasher.retention_target_dashboard_id', true
    ), '')::uuid
$function$;

CREATE FUNCTION dasher_private.security_policy_allows_v1(
  p_organization_id uuid,
  p_dashboard_id uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog
AS $function$
  SELECT current_user = 'dasher_security_definer'::name
    AND current_setting('dasher.security_phase', true) = 'authorized'
    AND current_setting('dasher.security_capability', true) IN (
      'request_agent_run', 'cancel_agent_run', 'read_agent_run'
    )
    AND COALESCE(current_setting('dasher.security_dashboard_id', true), '') <> ''
    AND p_organization_id = dasher_private.context_organization_id()
    AND p_dashboard_id = NULLIF(current_setting(
      'dasher.security_dashboard_id', true
    ), '')::uuid
    AND dasher_private.context_allows(p_organization_id, 'editor')
$function$;

REVOKE ALL ON FUNCTION dasher_private.run_policy_allows_v1(uuid, uuid, uuid)
  FROM PUBLIC;
REVOKE ALL ON FUNCTION dasher_private.retention_policy_allows_v1(uuid, uuid)
  FROM PUBLIC;
REVOKE ALL ON FUNCTION dasher_private.security_policy_allows_v1(uuid, uuid)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION dasher_private.run_policy_allows_v1(uuid, uuid, uuid)
  TO dasher_security_definer;
GRANT EXECUTE ON FUNCTION dasher_private.security_policy_allows_v1(uuid, uuid)
  TO dasher_run_definer;

